const fs = await import('node:fs');
const requestRef = process.env.TRILLION_HTTP_CLIENT_REQUEST_B64;
const raw = requestRef.startsWith('@file:') ? fs.readFileSync(requestRef.slice(6)) : Buffer.from(requestRef, 'base64');
const request = JSON.parse(raw.toString('utf8'));
const controller = new AbortController();
const timeout = setTimeout(() => controller.abort(), request.timeout_ms || 30000);
try {
  const body = request.body_file == null
    ? (request.body_b64 == null ? undefined : Buffer.from(request.body_b64, 'base64'))
    : fs.readFileSync(request.body_file);
  const response = await fetch(request.url, {
    method: request.method || 'GET',
    headers: request.headers || {},
    body,
    redirect: 'manual',
    signal: controller.signal,
  });
  const headers = Object.fromEntries(response.headers.entries());
  // DELIVER THE ANSWER WHILE IT IS STILL ARRIVING.
  //
  // The bytes of a long reply arrive continuously and were being collected into
  // a buffer that nobody could see until the last one landed. For the minute
  // before that, a reply on its way and a reply that is never coming look
  // exactly alike.
  //
  // The whole response is still returned, byte for byte, so every caller that
  // asked for nothing gets what it always got. The parts are an extra, sent to
  // wherever the caller said, and a delivery that fails NEVER fails the
  // request: the answer is the answer whether or not anyone watched it arrive.
  const deliverTo = request.deliver_parts_to;
  const collected = [];
  // What happened to the parts, reported beside the answer instead of vanishing.
  const parts = { sent: 0, failed: 0, last_error: null };
  if (deliverTo && response.body && response.status >= 200 && response.status < 300) {
    // THE WORDS OF A CONVERSATION GO NOWHERE BUT THIS MACHINE. The address is
    // DATA a participant row supplies, so without this a single row could post
    // every answer to any host on the internet.
    let target = null;
    try { target = new URL(deliverTo.url); } catch { target = null; }
    const loopback = target && target.protocol === 'http:' && ['127.0.0.1', 'localhost', '[::1]'].includes(target.hostname);
    if (!loopback) {
      parts.failed += 1;
      parts.last_error = 'parts address is not on this machine: ' + String(deliverTo.url);
    }
    // The receiver asks every caller to name which set of commands it is
    // talking to, and answers 428 with the right value when you do not. So the
    // first part asks, learns it from the refusal, and every part after that
    // already knows. Nothing secret is involved.
    let basis = null;
    const BASIS_HEADER = 'x-trillion-running-command-list-basis';
    const post = (payload) => fetch(deliverTo.url, {
      method: 'POST',
      headers: {
        'content-type': 'application/json',
        ...(basis ? { [BASIS_HEADER]: basis } : {}),
        ...(deliverTo.headers || {}),
      },
      body: JSON.stringify({ ...(deliverTo.with || {}), ...payload }),
      // A receiver that cannot answer quickly is not watching; the answer
      // itself must never wait on it.
      signal: AbortSignal.timeout(5000),
    });
    const sendOnce = async (payload) => {
      try {
        let reply = await post(payload);
        if (reply.status === 428) {
          basis = reply.headers.get(BASIS_HEADER)
            ?? (await reply.clone().json().catch(() => ({})))?.running_command_list_basis
            ?? null;
          if (basis) reply = await post(payload);
        }
        if (reply.ok) parts.sent += 1;
        else {
          parts.failed += 1;
          parts.last_error = 'status ' + reply.status + ': ' + (await reply.text().catch(() => '')).slice(0, 300);
        }
      } catch (error) {
        parts.failed += 1;
        parts.last_error = error instanceof Error ? error.message : String(error);
      }
    };
    // AT MOST ONE DELIVERY IN FLIGHT. Every delivery carries the whole answer so
    // far, so while one is in flight the newest bytes simply wait, and when it
    // returns the latest state goes out. Older states are never queued: they
    // are already contained in the newer one.
    let inFlight = null;
    let sentLength = 0;
    let sequence = 0;
    const flush = () => {
      if (!loopback || inFlight) return;
      const total = collected.reduce((sum, chunk) => sum + chunk.length, 0);
      if (total === sentLength) return;
      sentLength = total;
      sequence += 1;
      inFlight = sendOnce({ answer_so_far_base64: Buffer.concat(collected).toString('base64'), sequence })
        .finally(() => { inFlight = null; flush(); });
    };
    for await (const chunk of response.body) {
      collected.push(Buffer.from(chunk));
      flush();
    }
    // Let the last state go out, but never hold the finished answer for long.
    const settle = async () => {
      while (inFlight) await inFlight;
      flush();
      while (inFlight) await inFlight;
    };
    await Promise.race([settle(), new Promise((resolve) => setTimeout(resolve, 3000))]);
  }
  const responseBody = collected.length > 0
    ? Buffer.concat(collected)
    : Buffer.from(await response.arrayBuffer());
  process.stdout.write(JSON.stringify({
    status_code: response.status,
    headers,
    body_b64: responseBody.toString('base64'),
    ...(deliverTo ? { parts_delivery: parts } : {}),
  }));
} catch (error) {
  process.stderr.write(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
} finally {
  clearTimeout(timeout);
}
